#nullable enable
using Marten;
using Wolverine.Http;
using Wolverine.Marten;
using EmailOutbox.Contracts;

namespace EmailOutbox.Slices.EmailOutbox;

/// <summary>
/// THE ENDPOINT IS THE DECIDER. It takes the command, applies whatever rules need accumulated state, and
/// returns the event; <c>[EmptyResponse]</c> makes Wolverine *append* the returned event rather than
/// serialise it as a response body.
///
/// This slice has no state rules — see PrepareEmailState for why — so the decider is thin: mint the id,
/// stamp the clock, start the stream. Its one rule is periphery and lives in PrepareEmailValidator, which
/// Wolverine runs before this method is reached.
///
/// NOTE FOR THE KIT: nothing generated this file. codegen emits the command record, the state, the
/// validator and the tests, but not the endpoint — so a freshly generated command slice compiles and has no
/// way to be invoked. That is defensible (the endpoint holds business logic, and the generator emits none)
/// but it is not what a reader expects from "the generator is total", and unlike the trigger and
/// GenesisData it is not caught by the compiler because nothing references it.
/// </summary>
public static class PrepareEmailEndpoint
{
    public const string Route = "/emails";

    [WolverinePost(Route), EmptyResponse]
    public static (EmailPrepared, IStartStream) Prepare(PrepareEmail command)
    {
        // terminal="emailId:generated" — the screen cannot supply an id for a thing that does not exist
        // yet, so the handler mints it. terminal="preparedAt:clock" likewise. Both are on the model as
        // terminal= precisely so a reader knows they are NOT expected to arrive from upstream.
        var emailId = command.EmailId == Guid.Empty ? Guid.NewGuid() : command.EmailId;

        var prepared = new EmailPrepared(
            emailId, command.To, command.Subject, command.Body, DateTimeOffset.UtcNow);

        // StartStream rather than FetchForWriting: a new emailId means a stream that cannot already exist,
        // and asking Marten to start one makes that assumption explicit instead of implied.
        var start = MartenOps.StartStream<SendEmailState>(
            SendEmailState.StreamKey(emailId), prepared);

        return (prepared, start);
    }
}
